argetFile,		{				kOglRendererSourceFile,			0,			0		},		0,		0,		0,		"OpenGL"	}};resource 'infs' ( kOglRendererSourceFile ) {		'shlb',		'gld1',		0x0,		noSearchForFile,		TypeCrNeedNotMatch,		"MacVoodoo:parts:3dfx OpenGL Renderer"};resource 'intf' (kOglRendererTargetFile) {	format1 {		noSearchForFile, 		TypeCrMustMatch,		'shlb',		'gld1',		0,		1,		1,		0,		"special-extn:3dfx OpenGL Renderer"	}};